steps.script:
var ph = PhaseManager.get_current_phase_instance()
var found := false
for d in ph.dice_log:
	if str(d.get("context", "")) == "hit_roll_melee":
		print("[sw11e slayers] hit_roll_melee: weapon=", d.get("weapon", ""), " lethal=", d.get("lethal_hits_weapon", false), " crits=", d.get("critical_hits", 0))
		if bool(d.get("lethal_hits_weapon", false)):
			found = true
return found

var panel = tree.root.get_node("Main").get_node_or_null("HUD_Left/GameLogPanel")
if panel == null:
	for n in tree.root.get_node("Main").find_children("*", "", true, false):
		if n.get("_tab_dice_button") != null:
			panel = n
			break
if panel == null:
	return "panel not found"
panel._tab_dice_button.emit_signal("pressed")
return true

DebugLogger._flush_buffer()
var f = FileAccess.open(DebugLogger.get_log_file_path(), FileAccess.READ)
if f == null:
	return -1
var n = 0
var bad = []
while not f.eof_reached():
	var l = f.get_line()
	if l.contains("[ERROR"):
		n += 1
		bad.append(l)
print("[sw11e log] ", DebugLogger.get_real_log_file_path(), " ERROR lines = ", n, " ", bad.slice(0, 3))
return n
